function getAudioContext(){let C=window.AudioContext||window.webkitAudioContext;if(!C)return null;if(!audioContext)audioContext=new C;if(audioContext.state==='suspended')audioContext.resume();return audioContext}
function tone(ctx,freq,start,duration,type='sine',volume=.1){let osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain).connect(ctx.destination);osc.start(start);osc.stop(start+duration+.02)}
function noise(ctx,start,duration,volume=.045,highpass=300){let length=Math.ceil(ctx.sampleRate*duration),buffer=ctx.createBuffer(1,length,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length);let source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=buffer;filter.type='highpass';filter.frequency.value=highpass;gain.gain.setValueAtTime(volume,start);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);source.connect(filter).connect(gain).connect(ctx.destination);source.start(start)}
function sfx(type){if(!S.sound)return;let ctx=getAudioContext();if(!ctx)return;let now=ctx.currentTime+.015;if(type==='success'){tone(ctx,523,now,.18,'sine',.09);tone(ctx,659,now+.11,.2,'sine',.1);tone(ctx,784,now+.22,.34,'sine',.11)}else if(type==='victory'){[523,659,784,1047].forEach((f,i)=>tone(ctx,f,now+i*.16,.5,'sine',.12));tone(ctx,392,now,.9,'triangle',.04);tone(ctx,523,now+.72,1.15,'sine',.08);tone(ctx,784,now+.76,1.1,'sine',.065);noise(ctx,now+.58,.42,.018,1200);noise(ctx,now+.92,.55,.016,1400)}else if(type==='error'){tone(ctx,220,now,.22,'triangle',.09);tone(ctx,165,now+.13,.3,'triangle',.08)}else if(type==='select')tone(ctx,660,now,.08,'sine',.035);else if(type==='wind'){noise(ctx,now,1.25,.06,650);tone(ctx,440,now,.7,'sine',.018)}else if(type==='river'){noise(ctx,now,1.35,.052,180);tone(ctx,294,now,.75,'sine',.014)}else if(type==='wood'){tone(ctx,150,now,.11,'triangle',.09);tone(ctx,125,now+.15,.13,'triangle',.08);tone(ctx,175,now+.31,.12,'triangle',.08)}else if(type==='lantern'){tone(ctx,880,now,.35,'sine',.07);tone(ctx,1175,now+.16,.48,'sine',.055)}}
function musicNote(ctx,freq,start,duration,volume=.01,voice='flute'){let osc=ctx.createOscillator(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();osc.frequency.setValueAtTime(freq,start);filter.type='lowpass';filter.frequency.setValueAtTime(voice==='pluck'?2100:1450,start);osc.type=voice==='pluck'?'triangle':'sine';gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+(voice==='pluck' ? .012 : .14));if(voice==='pluck')gain.gain.exponentialRampToValueAtTime(.0001,start+duration);else{gain.gain.setValueAtTime(volume*.72,start+Math.max(.16,duration-.3));gain.gain.exponentialRampToValueAtTime(.0001,start+duration)}osc.connect(filter).connect(gain).connect(ctx.destination);osc.start(start);osc.stop(start+duration+.03);musicNodes.push(osc);osc.onended=()=>{musicNodes=musicNodes.filter(n=>n!==osc)}}
function musicPhrase(){if(!S.sound||S.view!=='game')return;let ctx=getAudioContext();if(!ctx)return;let now=ctx.currentTime+.06,scale=[293.66,329.63,369.99,440,493.88,587.33],phrases=[[0,2,3,4,3,2,0,1,2,0],[2,3,5,4,3,2,1,0,2,1],[0,1,2,4,3,2,0,2,1,0],[3,4,5,4,2,3,2,1,0,1]],rhythm=[.58,.58,.82,.58,.58,.82,.58,.58,.82,.9],melody=phrases[musicStep++%phrases.length],time=now;musicNote(ctx,scale[0]/2,now,5.9,.009,'flute');musicNote(ctx,scale[3]/2,now+.04,5.7,.0065,'flute');melody.forEach((n,i)=>{let d=rhythm[i];musicNote(ctx,scale[n],time,d*.9,.021,'flute');if(i%2===0)musicNote(ctx,scale[Math.max(0,n-2)]*2,time+.025,.13,.012,'pluck');if(i===3||i===7)musicNote(ctx,scale[4]*2,time+.12,.65,.006,'flute');time+=d});[0,1.98,3.96].forEach((t,i)=>musicNote(ctx,scale[[0,3,2][i]],now+t,.18,.009,'pluck'))}
