function legendView(){return `<section class="legend"><header class="legend__hero"><div><small>十二生肖的故事</small><h2>Легенда о китайском зодиаке</h2><p>Прочитай историю на китайском языке, послушай произношение и проверь перевод.</p></div></header><div class="legend__chapters">${LEGEND.map((x,i)=>`<article class="legend-card"><span class="legend-card__number">${i+1}</span><div class="legend-card__animals">${x.animals.length?x.animals.map(n=>animalArt(A[n],'legend-animal')).join(''):`<span class="legend-emperor">玉</span>`}</div><div class="legend-card__text"><p class="legend-cn">${x.cn}</p><p class="legend-pinyin">${x.py}</p><p class="legend-translation">${x.ru}</p></div><button class="legend-sound speak" data-say="${x.cn}" aria-label="Прослушать китайский текст">${mark('声')}<span>Послушать</span></button></article>`).join('')}</div><footer class="legend__order"><h3>Порядок животных</h3><div>${A.map((a,i)=>`<span>${animalArt(a,'legend-order-animal')}<b>${i+1}. ${a.hanzi}</b><small>${a.pinyin}</small></span>`).join('')}</div></footer></section>`}
function info(type){if(type==='dictionary')openModal(`<section class="dictionary"><header class="dictionary__head"><div><small>十二生肖</small><h2>Словарь зодиака</h2><p>Рассмотри животное и нажми кнопку, чтобы услышать правильное произношение.</p></div></header><div class="dictionary__grid">${A.map((a,i)=>`<article class="dictionary-card"><span class="dictionary-card__number">${i+1}</span>${animalArt(a,'dictionary-animal')}<div class="dictionary-card__word"><b>${a.hanzi}</b><span>${a.pinyin}</span><small>${a.ru}</small></div><button class="dictionary-sound speak" data-say="${a.pinyin}" title="Прослушать: ${a.pinyin}" aria-label="Прослушать слово ${a.pinyin}">${mark('声')}<span>Слушать</span></button></article>`).join('')}</div></section>`,true);else openModal(legendView(),true)}

document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.classList.contains('modal__close'))closeModal();if(b.dataset.view){closeModal();S.view=b.dataset.view;render()}if(b.dataset.info)info(b.dataset.info);if(b.dataset.game!=null)startGame(+b.dataset.game);if(b.dataset.mode){S.mode=b.dataset.mode;S.step=0;S.sudoku=null;S.find=null;S.sentence=null;render()}if(b.dataset.roadAnimal!=null){S.roadAnimal=A[+b.dataset.roadAnimal];road()}if(b.dataset.toggle){S[b.dataset.toggle]=!S[b.dataset.toggle];save();gameShell()}if(b.dataset.road!=null)roadCard(+b.dataset.road);if(b.classList.contains('road-choice')){S.choice=b.dataset.answer;$$('.road-choice').forEach(x=>x.classList.toggle('selected',x===b));$('#roadCheck').disabled=false}if(b.id==='roadCheck')checkRoad();if(b.dataset.sudokuToken!=null){S.sudoku.pick=+b.dataset.sudokuToken;$$('.sudoku-token').forEach(x=>x.classList.toggle('selected',x===b))}if(b.dataset.sudokuCell!=null)putSudoku(b);if(b.id==='sudokuHint')sudokuHint();if(b.id==='nextSudoku'){closeModal();gameShell()}if(b.dataset.screen!=null)selectScreen(+b.dataset.screen);if(b.classList.contains('shadow-token'))chooseShadowToken(b);if(b.dataset.shadowSlot!=null)dropShadow(+b.dataset.shadowSlot,b.dataset.type);if(b.id==='shadowHint')shadowHint();if(b.dataset.findCell!=null)selectFind(+b.dataset.findCell);if(b.classList.contains('sentence-token')){let i=S.sentence.placed.findIndex(x=>!x);if(i<0)i=S.sentence.placed.length;placeSentence(i,b.dataset.word)}if(b.dataset.position!=null&&S.sentence?.selected)placeSentence(+b.dataset.position,S.sentence.selected);if(b.id==='sentenceCheck')checkSentence();if(b.id==='sentenceHint')sentenceHint();if(b.id==='pinyinToggle'){$$('.sentence-token').forEach(x=>{let i=S.sentence.q.w.indexOf(x.dataset.word);if(i>=0)x.innerHTML=`${x.dataset.word}<small>${S.sentence.q.p[i]}</small>`})}if(b.classList.contains('final-choice')){if(+b.dataset.final===S.finalAnimal.i){let done=S.finalDone;S.finalDone=null;done()}else{S.errors++;feedback('Это другое животное. Попробуй ещё раз.',false)}}if(b.classList.contains('speak'))speak(b.dataset.say);if(b.id==='sound'){S.sound=!S.sound;save();render()}if(b.dataset.replay!=null){closeModal();startGame(+b.dataset.replay)}});
document.addEventListener('dragstart',e=>{let b=e.target.closest('[draggable="true"]');if(!b)return;if(b.dataset.sudokuToken!=null){S.sudoku.pick=+b.dataset.sudokuToken;e.dataTransfer.setData('text/plain','sudoku')}else if(b.classList.contains('shadow-token')){S.shadows.token={type:b.dataset.shadowType,value:b.dataset.value};e.dataTransfer.setData('text/plain','shadow')}else if(b.classList.contains('sentence-token'))e.dataTransfer.setData('text/plain',`sentence:${b.dataset.word}`)});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-sudoku-cell],[data-shadow-slot],[data-position]'))e.preventDefault()});
document.addEventListener('drop',e=>{let target=e.target.closest('[data-sudoku-cell],[data-shadow-slot],[data-position]');if(!target)return;e.preventDefault();let data=e.dataTransfer.getData('text/plain');if(data==='sudoku')putSudoku(target);if(data==='shadow')dropShadow(+target.dataset.shadowSlot,target.dataset.type);if(data.startsWith('sentence:'))placeSentence(+target.dataset.position,data.slice(9))});
document.addEventListener('click',e=>{let b=e.target.closest('[data-road-special]');if(b)roadSpecialClick(b);else{let button=e.target.closest('button');if(button){sfx('select');if(button.dataset.game!=null||button.dataset.replay!=null)setTimeout(startMusic,80);if(button.id==='sound'){if(S.sound)startMusic();else stopMusic()}if(button.dataset.view==='home')stopMusic();if(+button.dataset.road===7)setTimeout(()=>sfx('river'),90)}}});
document.addEventListener('pointerdown',()=>{if(S.view==='game'&&S.sound){getAudioContext();startMusic()}},{passive:true});
